import zipfile
import xml.etree.ElementTree as ET
import re
import sys

path = "budget.xlsx"

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1, row - 1  # 0-based col, 0-based row

def parse_workbook(z):
    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.attrib["Id"]: r.attrib["Target"] for r in rels}
    sheets = []
    for sh in wb_xml.find("m:sheets", NS):
        rid = sh.attrib["{%s}id" % NS["r"]]
        sheets.append((sh.attrib["name"], rel_map[rid].lstrip("/")))
    return sheets

def parse_shared_strings(z):
    try:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    except KeyError:
        return []
    out = []
    for si in root.findall("m:si", NS):
        parts = [t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")]
        out.append("".join(parts))
    return out

def parse_sheet(z, path, shared):
    root = ET.fromstring(z.read(path))
    rows = {}
    for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
        ref = c.attrib.get("r")
        if not ref:
            continue
        col, row = col_to_idx(ref)
        t = c.attrib.get("t")
        v = c.find("m:v", NS)
        val = ""
        if v is not None:
            if t == "s":
                val = shared[int(v.text)]
            elif t == "str" or t == "inlineStr":
                val = v.text or ""
            else:
                val = v.text or ""
        else:
            is_el = c.find("m:is", NS)
            if is_el is not None:
                val = "".join(x.text or "" for x in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        rows.setdefault(row, {})[col] = val
    max_row = max(rows) + 1 if rows else 0
    max_col = max(max((cols.keys() for cols in rows.values()), default=[]), default=-1) + 1
    grid = []
    for r in range(max_row):
        grid.append([rows.get(r, {}).get(c, "") for c in range(max_col)])
    return grid

def to_number(s):
    try:
        return float(s)
    except (TypeError, ValueError):
        return None

with zipfile.ZipFile(path) as z:
    shared = parse_shared_strings(z)
    for name, target in parse_workbook(z):
        if target.startswith("/"):
            target = target[1:]
        elif not target.startswith("xl/"):
            target = "xl/" + target
        grid = parse_sheet(z, target, shared)
        print(f"=== Sheet: {name} ===")
        for row in grid:
            print(row)

